INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3003, 'ko-KR', 'name', '개인정보 보호정책', 'reviewed', SHA2('隐私协议', 256), NULL, NULL, 1, '2026-08-03 16:49:48', 1, 1, '2026-08-03 16:49:48', '2026-08-03 16:49:48', 0);
INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3003, 'ko-KR', 'value', '<h2>개인정보취급방침</h2><p>이 애플리케이션을 사용해 주셔서 감사합니다. 당사는 귀하의 개인정보를 소중히 여기고 보호하며, 계정 로그인, 애플리케이션 기능, 고객 서비스 제공을 위해 필요한 경우에만 이를 처리합니다.</p><h3>I. 정보 이용</h3><p>당사는 귀하의 정보를 해당 법률 및 본 정책에 따라 사용하며, 관련없는 목적으로 사용하지 않습니다.</p><h3>II. 귀하의 권리</h3><p>귀하는 법률에 따라 귀하의 개인정보에 접근, 수정, 삭제할 수 있으며, 애플리케이션에 게시된 채널을 통해 당사에 문의하실 수 있습니다.</p>', 'reviewed', SHA2('<h2>隐私政策</h2><p>感谢您使用本应用。我们重视并保护您的个人信息，仅在提供账号登录、应用功能和客户服务所必需的范围内处理相关信息。</p><h3>一、信息使用</h3><p>我们会按照法律法规和本协议约定使用您的信息，不会将其用于无关目的。</p><h3>二、您的权利</h3><p>您可以依法查询、更正、删除个人信息，或通过应用内公布的渠道联系我们。</p>', 256), NULL, NULL, 1, '2026-08-03 16:49:48', 1, 1, '2026-08-03 16:49:48', '2026-08-03 16:49:48', 0);
INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3004, 'ko-KR', 'name', '서비스 약관', 'reviewed', SHA2('服务条款', 256), NULL, NULL, 1, '2026-08-03 16:49:48', 1, 1, '2026-08-03 16:49:48', '2026-08-03 16:49:48', 0);
INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3004, 'ko-KR', 'value', '<h2>서비스 약관</h2><p>이 애플리케이션에 오신 것을 환영합니다. 애플리케이션을 사용하기 전에 본 계약 및 관련 규칙을 읽고 이해하십시오. 애플리케이션 서비스를 사용함으로써 귀하는 해당 서비스를 준수하는 데 동의합니다.</p><h3>I. 서비스 이용</h3><p>각 기능을 페이지의 지침에 따라 합법적으로 사용하시기 바랍니다. 불법적인 행위나 타인의 권리를 침해하는 행위에 본 애플리케이션을 사용해서는 안됩니다.</p><h3>II. 계약 변경</h3><p>당사는 비즈니스, 법률 및 규정의 변경에 따라 본 계약을 업데이트할 수 있으며 업데이트된 버전을 애플리케이션에 표시합니다.</p>', 'reviewed', SHA2('<h2>服务条款</h2><p>欢迎使用本应用。使用本应用前，请您阅读并理解本协议。您开始使用应用服务，即表示同意遵守本协议及相关规则。</p><h3>一、服务使用</h3><p>请您依法、合规并按照页面提示使用各项功能，不得利用本应用从事违法或损害他人权益的活动。</p><h3>二、协议变更</h3><p>我们会根据业务和法律法规变化更新本协议，并在应用内向您展示更新后的内容。</p>', 256), NULL, NULL, 1, '2026-08-03 16:49:48', 1, 1, '2026-08-03 16:49:48', '2026-08-03 16:49:48', 0);
